234: ## Exception Testing
235: 
236: ```dart
237: class Calculator {
238:   int divide(int a, int b) {
239:     if (b == 0) throw ArgumentError('Cannot divide by zero');
240:     return a ~/ b;
241:   }
242: }
243: 
244: // Test
245: test('divide throws when dividing by zero', () {
246:   final calculator = Calculator();
247:   expect(
248:     () => calculator.divide(10, 0),
249:     throwsArgumentError,
250:   );
251: });
252: 
253: test('divide throws with specific message', () {
254:   final calculator = Calculator();
255:   expect(
256:     () => calculator.divide(10, 0),
257:     throwsA(isA<ArgumentError>()
258:       .having((e) => e.message, 'message', contains('zero'))),
259:   );
260: });
261: ```
