488: ### State-Based Mock
489: 
490: ```dart
491: class StatefulMockService implements ApiService {
492:   final List<String> responses = [];
493:   int _callCount = 0;
494:   
495:   @override
496:   Future<String> fetchData() async {
497:     if (_callCount < responses.length) {
498:       return responses[_callCount++];
499:     }
500:     throw Exception('No more responses');
501:   }
502:   
503:   void addResponse(String response) {
504:     responses.add(response);
505:   }
506: }
507: 
508: // Test
509: test('returns sequential responses', () async {
510:   final mock = StatefulMockService();
511:   mock.addResponse('first');
512:   mock.addResponse('second');
513:   
514:   expect(await mock.fetchData(), 'first');
515:   expect(await mock.fetchData(), 'second');
516:   
517:   await expectLater(mock.fetchData(), throwsException);
518: });
519: ```
